"use client";

import { useTheme } from "@providers/ThemeProvider";
import Image from "next/image";

export default function SideBarSmall() {
  const { theme } = useTheme();
  const darkTheme = theme === "dark";

  const sidebarItems = [
    { icon: "", label: "" },
    { icon: "", label: "" },
  ];

  return (
    <div className={`w-full h-full ${
          darkTheme
            ? "bg-dark-black-primary text-dark-white-primary"
            : "bg-light-white-primary text-light-black-primary"
        }`}>
      <div className="w-full h-full flex flex-col p-4 gap-6">
        
        {/* Logo Section */}
        <div className="flex items-center gap-2">
          <Image
            src={`/logos/${darkTheme ? "logo-white" : "logo-black"}.png`}
            alt="Woah AI"
            width={24}
            height={24}
          />
        </div>

        {/* Sidebar Options */}
        <div className="flex flex-col gap-4 items-center">
          {sidebarItems.map((item, idx) => (
            <div
              key={idx}
              className={`flex items-center justify-center rounded-lg cursor-pointer transition-colors duration-200 hover:bg-opacity-10 ${
                darkTheme ? "text-white hover:bg-white" : "text-black hover:bg-black"
              }`}
            >
              {/* Replace with real icon if needed */}
              <span className="w-[20px] h-[20px] rounded-full bg-gray-400"></span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
