// AppContext.tsx
type AppContextType = {
  sidebarExpanded: boolean;
  setSidebarExpanded: (value: boolean) => void;
  toggleSidebar: () => void;

  searchActive: boolean;
  setSearchActive: (value: boolean) => void;
  toggleSearch: () => void;

  moreBarVisible: boolean;
  setMoreBarVisible: (value: boolean) => void;
  toggleMoreBar: () => void;
};

export function AppProvider({ children }: { children: ReactNode }) {
  const [sidebarExpanded, setSidebarExpanded] = useState(false);
  const [searchActive, setSearchActive] = useState(false);
  const [moreBarVisible, setMoreBarVisible] = useState(false);

  const toggleSidebar = () => setSidebarExpanded(prev => !prev);
  const toggleSearch = () => setSearchActive(prev => !prev);
  const toggleMoreBar = () => setMoreBarVisible(prev => !prev);

  return (
    <AppContext.Provider
      value={{
        sidebarExpanded,
        setSidebarExpanded,
        toggleSidebar,
        searchActive,
        setSearchActive,
        toggleSearch,
        moreBarVisible,
        setMoreBarVisible,
        toggleMoreBar
      }}
    >
      {children}
    </AppContext.Provider>
  );
}
